  ["Report %s, %d characters, selected: press Ctrl+C to copy it."] = "Rapport %s, %d caractères, sélectionné : appuyez sur Ctrl+C pour le copier.",
  ["Report a problem"] = "Signaler un problème",
  ["Report an issue"] = "Signaler un problème",
  ["Report failed"] = "Échec du rapport",
  ["Report too large"] = "Rapport trop grand",
  ["Reporting a problem"] = "Signaler un problème",
  ["Reset everything to defaults"] = "Tout remettre par défaut",
  ["Right after it happens: /dmga report (or the minimap menu, or Status > Report an issue). Step 1: say what went wrong. Step 2: Ctrl+C copies your words and the report together. Step 3: open the link and paste it into a new issue. /dmga help lists every command."] = "Juste après le problème : /dmga report (ou le menu de la minicarte, ou État > Signaler un problème). Étape 1 : dites ce qui s'est mal passé. Étape 2 : Ctrl+C copie vos mots et le rapport ensemble. Étape 3 : ouvrez le lien et collez le tout dans un nouveau ticket. /dmga help liste toutes les commandes.",
  ["Right-click: menu and settings"] = "Clic droit : menu et options",
  ["Rotation by %s."] = "Rotation par %s.",
  ["Rotation from"] = "Rotation de",
  ["Run the setup again"] = "Relancer la configuration",
  ["Saves every line the engine checked into the Watchdog log (same as /dmga snapshot)."] = "Enregistre chaque ligne vérifiée par le moteur dans le journal du Watchdog (comme /dmga snapshot).",
  ["Scale"] = "Échelle",
  ["Seconds before the hit your boss mod announces."] = "Secondes avant le coup annoncé par votre addon de boss.",
  ["Self-heal below"] = "Soin personnel à",
  ["Self-heals"] = "Soins personnels",
  ["Self-heals in raids"] = "Soins personnels en raid",
  ["Self-heals your rotation can suggest (Desperate Prayer, Regrowth, Crimson Vial...) show only at or below this health. 0 = never."] = "Les soins personnels que votre rotation peut proposer (Prière du désespoir, Rétablissement, Fiole cramoisie...) n'apparaissent qu'à cette vie ou moins. 0 = jamais.",
  ["Set key bindings"] = "Définir les raccourcis",
  ["Settings"] = "Options",
  ["Settings copied from %s into %s."] = "Options copiées de %s vers %s.",
  ["Settings open when combat ends."] = "Les options s'ouvriront à la fin du combat.",
  ["Settings this character uses. \"Default\" is shared by every character that has no profile of its own."] = "Options utilisées par ce personnage. « Default » est partagé par tous les personnages sans profil propre.",
  ["Detect boss mods"] = "Afficher les addons de boss trouvés",
  ["Show out of combat"] = "Afficher hors combat",
  ["Show recommendations"] = "Afficher les recommandations",
  ["Show stack count"] = "Afficher le nombre de cumuls",
  ["Show the HUD out of combat while an enemy is targeted."] = "Afficher le HUD hors combat quand un ennemi est ciblé.",
  ["Show with a target"] = "Afficher avec une cible",
  ["Show your on-use trinkets (off-GCD badge on slot 1) when they are ready, with your cooldowns, in combat."] = "Afficher vos bijoux à utiliser (badge hors GCD sur la case 1) quand ils sont prêts, avec vos temps de recharge, en combat.",
  ["SimC default (300 s bosses, short trash)"] = "Valeur SimC (300 s boss, trash court)",
  ["SimC holds or uses cooldowns by how long the fight lasts. Learned: the typical length of your recent fights of the same kind (open world, dungeon/raid trash, bosses, PvP); SimC's defaults until it has 5."] = "SimC garde ou utilise les temps de recharge selon la durée du combat. Appris : la durée typique de vos combats récents du même type (monde ouvert, trash de donjon/raid, boss, JcJ) ; les valeurs de SimC jusqu'à en avoir 5.",
  ["SimulationCraft publishes no rotation for most healing specs (Discipline, Holy Priest, Holy Paladin, Mistweaver, Restoration Shaman, Preservation). For those DMGAssist has its own damage lists, learned from the current class guides, for your damage between heals (SimC's list replaces ours as soon as it publishes one). Healing stays your call. Interrupts, defensives with your boss mod, on-use trinkets, keybinds and your spell choices all work. Restoration Druid has a full SimC list, including cat weaving. A spec with no list at all (some on WoW Forever) follows Blizzard's Assisted Combat."] = "SimulationCraft ne publie pas de rotation pour la plupart des spécialisations de soin (Discipline, Sacré (prêtre), Sacré (paladin), Tisse-brume, Restauration (chaman), Préservation). Pour elles, DMGAssist a ses propres listes de dégâts, apprises des guides de classe actuels, pour vos dégâts entre les soins (la liste de SimC remplace la nôtre dès qu'elle en publie une). Les soins restent votre choix. Interruptions, défensifs avec votre addon de boss, bijoux, raccourcis et vos choix de sorts fonctionnent. Restauration (druide) a une liste SimC complète, y compris le tissage en félin. Une spécialisation sans aucune liste (certaines sur WoW Forever) suit le Combat assisté de Blizzard.",
  ["Single target"] = "Cible unique",
  ["Size, as a percentage of slot 1."] = "Taille, en pourcentage de la case 1.",
  ["Skip the spell in slot 1 three times and it is held for the rest of the fight (\"saving it\"). Cast it yourself and it comes back. Only spells with a real cooldown are held."] = "Passez le sort de la case 1 trois fois et il est retenu pour le reste du combat (« le garder »). Lancez-le vous-même et il revient. Seuls les sorts avec un vrai temps de recharge sont retenus.",
  ["Skip the spell in the first slot three times and it is held until combat ends. Cast it yourself to bring it back."] = "Passez le sort de la première case trois fois et il est retenu jusqu'à la fin du combat. Lancez-le vous-même pour le faire revenir.",
  ["Skipping a spell"] = "Passer un sort",
  ["Small"] = "Petit",
  ["Smart: all in the open world, important ones in instances"] = "Intelligent : tout en monde ouvert ; en donjon/raid seulement ce qui compte",
  ["Smart: boss mod warnings and low health"] = "Intelligent : alertes des addons de boss et vie basse",
  ["Snapshot"] = "Instantané",
  ["Snapshot: %s (%s), %d lines checked. Stored for your report: /dmga report."] = "Instantané : %s (%s), %d lignes vérifiées. Enregistré pour votre rapport : /dmga report.",
  ["Sound alerts"] = "Alertes sonores",
  ["Sounds"] = "Sons",
  ["Spec changed: %s"] = "Spécialisation changée : %s",
  ["Spell name color"] = "Couleur du nom du sort",
  ["Spell name size"] = "Taille du nom du sort",
  ["Spell names under icons"] = "Noms des sorts sous les icônes",
  ["Spells & trinkets"] = "Sorts et bijoux",
  ["Spells & trinkets: untick a spell or trinket to never see it, or tick First when ready to put a spell in slot 1 whenever it can be cast. Kept per spec, through updates."] = "Sorts et bijoux : décochez un sort ou un bijou pour ne jamais le voir, ou cochez En premier dès que prêt pour placer un sort dans la case 1 dès qu'il peut être lancé. Gardé par spécialisation, même après les mises à jour.",
  ["Spells in the list you don't have (or we can't match): %s"] = "Sorts de la liste que vous n'avez pas (ou que nous ne reconnaissons pas) : %s",
  ["Spells matched: %s. Type /dmga help for options."] = "Sorts reconnus : %s. Tapez /dmga help pour les options.",
  ["Rotation spells known"] = "Sorts de la rotation que vous avez",
  ["Spells shown"] = "Sorts affichés",
  ["Stack count"] = "Cumuls",
  ["Stack position"] = "Position des cumuls",
  ["Stack text size"] = "Taille du texte des cumuls",
  ["Starts as a copy of the current settings; other characters are not affected."] = "Commence comme copie des options actuelles ; les autres personnages ne sont pas concernés.",
  ["Status"] = "État",
  ["Steady"] = "Fixe",
  ["Save a decision snapshot"] = "Enregistrer un instantané de décision",
  ["Suggest a defensive this long before a big hit that a boss mod announces."] = "Proposer un défensif autant de temps avant un gros coup annoncé par un addon de boss.",
  ["Suggest defensives"] = "Proposer des défensifs",
  ["Suggest interrupts"] = "Proposer des interruptions",
  ["Summary (for reading; the report is what to paste)"] = "Résumé (à lire ; c'est le rapport qu'il faut coller)",
  ["Target mode keybind"] = "Changer avec une touche",
  ["Talents loaded"] = "Talents lus",
  ["Tank essentials"] = "Essentiels du tank",
  ["Tanks: keep active mitigation and your threat DoT up (Guardian: Ironfur stacks, Moonfire on the target)."] = "Tanks : garder la mitigation active et votre DoT de menace (Gardien : cumuls de Fourrure de fer, Éclat lunaire sur la cible).",
  ["Target mode"] = "Mode de cibles",
  ["Target mode: %s."] = "Mode de cibles : %s.",
  ["Targets"] = "Cibles",
  ["Test"] = "Tester",
  ["Defensive test: slot 1 shows %s for 8 seconds."] = "Alerte défensive de test pendant 8 s : la case 1 montre %s, comme quand DBM / BigWigs / LittleWigs annoncent un gros coup.",
  ["Interrupt test: slot 1 shows %s for 8 seconds."] = "Interruption de test pendant 8 s : la case 1 montre %s, comme quand un addon de boss demande un kick ou que votre cible incante.",
  ["Text"] = "Texte",
  ["The DMGAssist_Watchdog addon (Report an issue) is not installed."] = "L'addon DMGAssist_Watchdog (Signaler un problème) n'est pas installé.",
  ["The Default profile can't be deleted."] = "Le profil Default ne peut pas être supprimé.",
  ["The HUD is unlocked: drag it where you like, then lock it in Settings > DMGAssist."] = "Le HUD est déverrouillé : glissez-le où vous voulez, puis verrouillez-le dans Options > DMGAssist.",
  ["The icons"] = "Les icônes",
  ["The main icon is darkened until your GCD or cast is about to end, then flashes: press it then."] = "L'icône principale est assombrie jusqu'à ce que votre GCD ou incantation soit presque fini, puis elle clignote : appuyez à ce moment-là.",
  ["The next spell, plus up to two after it."] = "Le prochain sort, plus jusqu'à deux après.",
  ["Shows where each pick came from: SimC, Assisted Combat, Blizzard rules, or a guess."] = "La file avec l'origine de chaque choix (SimC, assistant, règles de Blizzard, estimation).",
  ["The report could not be built:"] = "Le rapport n'a pas pu être créé :",
  ["The report did not fit in the window. Type /dmgw status and paste what it prints instead."] = "Le rapport ne tenait pas dans la fenêtre. Tapez /dmgw status et collez plutôt ce qui s'affiche.",
  ["Thick"] = "Épais",
  ["Thick outline"] = "Contour épais",
  ["Thin"] = "Fin",
  ["This character"] = "Ce personnage",
  ["This character now has its own profile: %s."] = "Ce personnage a maintenant son propre profil : %s.",
  ["Three questions: where the HUD goes, how big, and when it shows."] = "Trois questions : où va le HUD, quelle taille, et quand il s'affiche.",
  ["To report a problem or give feedback: press Report an issue (or type /dmga report). It walks you through it: say what went wrong, copy the report, paste it on the issue page."] = "Pour signaler un problème ou donner un avis : appuyez sur Signaler un problème (ou tapez /dmga report). Il vous guide : dites ce qui s'est mal passé, copiez le rapport, collez-le sur la page des tickets.",
  ["Top left"] = "En haut à gauche",
  ["Top right"] = "En haut à droite",
  ["Top-left corner (docked)"] = "Coin supérieur gauche (ancré)",
  ["Top-right corner"] = "Coin supérieur droit",
  ["Trinkets"] = "Bijoux",
  ["Troubleshooting"] = "Dépannage",
  ["Show both options when unsure"] = "Embranchements à deux sorts",
  ["Unlock to drag the icons; they are also shown while this panel is open."] = "Déverrouillez pour glisser les icônes ; elles sont aussi affichées tant que ce panneau est ouvert.",
  ["Upcoming adds, AoE, tank hits and interrupts: used for defensives, interrupts and SimC's add timing."] = "Adds, zone, coups sur le tank et interruptions à venir : utilisés pour les défensifs, les interruptions et le timing des adds de SimC.",
  ["Use a profile for this character only"] = "Utiliser un profil pour ce personnage uniquement",
  ["Use major cooldowns"] = "Utiliser les temps de recharge sur",
  ["Use the suggestions"] = "Utiliser les suggestions",
  ["Used when \"AoE target count\" is Custom: this many targets or more counts as AoE."] = "Utilisé quand « Nombre de cibles pour la zone » est Personnalisé : à partir de ce nombre de cibles, c'est de la zone.",
  ["Used when the count isn't available. The key binding switches during a fight."] = "Utilisé quand le nombre n'est pas disponible. Le raccourci change le mode pendant un combat.",
  ["Version"] = "Version",
  ["Warn about missing keybinds"] = "Avertir des raccourcis manquants",
  ["Warning: data for %s loaded at once; using %s."] = "Attention : les données de %s ont été chargées en même temps ; %s est utilisé.",
  ["Watchdog (diagnostics)"] = "Watchdog (diagnostic)",
  ["Welcome to DMGAssist"] = "Bienvenue dans DMGAssist",
  ["What were you doing? (for example: 5 dummies, a Mythic+ pull, a raid boss, solo)"] = "Que faisiez-vous ? (par exemple : 5 mannequins, un pull en mythique+, un boss de raid, en solo)",
  ["When"] = "Quand",
  ["When a hidden resource decides (e.g. 4 or 5 combo points), show both spells; the game makes the right one visible."] = "Quand une ressource cachée décide (p. ex. 4 ou 5 points de combo), afficher les deux sorts ; le jeu rend le bon visible.",
  ["When should it show?"] = "Quand doit-il s'afficher ?",
  ["When to show"] = "Quand afficher",
  ["When your boss mod warns of AoE damage, show Power Word: Radiance, then Shield, until enough Atonements are up."] = "Quand votre addon de boss annonce des dégâts de zone, afficher Mot de pouvoir : Radiance, puis Bouclier, jusqu'à avoir assez d'Expiations.",
  ["Where should the recommendations go?"] = "Où mettre les recommandations ?",
  ["Where the rotation comes from"] = "D'où vient la rotation",
  ["Where the small badge for spells pressed alongside slot 1 (no GCD, e.g. Ironfur) sits."] = "Où se place le petit badge des sorts appuyés en même temps que la case 1 (sans GCD, p. ex. Fourrure de fer).",
  ["Whisper"] = "Chuchotement",
  ["With \"Bosses and big pulls\": this many enemies or more counts as a big pull."] = "Avec « Boss et gros pulls » : à partir de ce nombre d'ennemis, c'est un gros pull.",
  ["With DBM, BigWigs or LittleWigs, a defensive is shown a few seconds before a big hit they warn about (lighter ones first; on cooldown, the next). Also when you are low. Integrations has buttons to test both."] = "Avec DBM, BigWigs ou LittleWigs, un défensif est affiché quelques secondes avant un gros coup qu'ils annoncent (les plus légers d'abord ; en recharge, le suivant). Aussi quand votre vie est basse. Intégrations a des boutons pour tester les deux.",
  ["With a controller (the game's gamepad support), keybinds show as controller buttons, for example LT+A."] = "Avec une manette (la prise en charge des manettes du jeu), les raccourcis s'affichent comme des boutons de manette, par exemple LT+A.",
  ["Xbox (A B X Y, LB RB)"] = "Xbox (A B X Y, LB RB)",
  ["You have unspent talent points: press N to open your talents."] = "Il vous reste des points de talent : appuyez sur N pour ouvrir vos talents.",
  ["You know enough of this spec's spells now: DMGAssist's priority list leads."] = "Vous connaissez maintenant assez de sorts de cette spécialisation : la liste de priorités de DMGAssist mène.",
  ["Your choices"] = "Vos choix",
  ["Spec default"] = "Point de bascule de votre spécialisation",
  ["Your spec's switch point comes from its SimC list (when it uses an AoE list): the count where it changes."] = "Le point de bascule de votre spécialisation vient de sa liste SimC (quand elle utilise une liste de zone) : le nombre où elle change.",
  ["available (used as a second opinion)"] = "disponible (utilisé comme second avis)",
  ["held"] = "retenu",
  ["installed"] = "installé",
  ["learned"] = "appris",
  ["learning (SimC default until then)"] = "en apprentissage : valeur SimC pour l'instant",
  ["leveling: following Blizzard's Assisted Combat until you know more of this spec's spells"] = "montée de niveau : suit le Combat assisté de Blizzard jusqu'à ce que vous connaissiez plus de sorts de cette spécialisation",
  ["manual"] = "manuel",
  ["no"] = "non",
  ["no SimC list for this spec: DMGAssist's own list, learned from the class guides"] = "pas de liste SimC pour cette spécialisation : liste propre de DMGAssist, apprise des guides de classe",
  ["no SimC list for this spec: following Blizzard's Assisted Combat"] = "pas de liste SimC pour cette spécialisation : suit le Combat assisté de Blizzard",
  ["none"] = "aucun",
  ["none available"] = "aucun disponible",
  ["none set (Settings > DMGAssist > Set key bindings)"] = "aucun défini (Options > DMGAssist > Définir les raccourcis)",
  ["not available"] = "non disponible",
  ["not installed"] = "non installé",
  ["not on your bars"] = "pas sur vos barres",
  ["off"] = "désactivé",
  ["on a bar, no key"] = "sur une barre, sans touche",
  ["ready"] = "prêt",
  ["starter spec: following Blizzard's Assisted Combat until you choose a specialization"] = "spécialisation de départ : suit le Combat assisté de Blizzard jusqu'à ce que vous choisissiez une spécialisation",
  ["target"] = "cible",
  ["targets"] = "cibles",
  ["then paste your report with |cffffffffCtrl+V|r and press Create. A screenshot helps too."] = "puis collez votre rapport avec |cffffffffCtrl+V|r et appuyez sur Create. Une capture d'écran aide aussi.",
  ["trinket"] = "bijou",
  ["trinket, bottom slot"] = "bijou, emplacement du bas",
  ["trinket, top slot"] = "bijou, emplacement du haut",
  ["yes"] = "oui",
  ["|cffffd100Step 1.|r What went wrong? What did you expect instead?"] = "|cffffd100Étape 1.|r Qu'est-ce qui s'est mal passé ? Qu'attendiez-vous à la place ?",
  ["|cffffd100Step 2.|r Click the box below and press |cffffffffCtrl+C|r. Your words above are included."] = "|cffffd100Étape 2.|r Cliquez dans la case ci-dessous et appuyez sur |cffffffffCtrl+C|r. Vos mots ci-dessus sont inclus.",
  ["|cffffd100Step 3.|r Open this page in your browser (click it, Ctrl+C, paste it in the address bar),"] = "|cffffd100Étape 3.|r Ouvrez cette page dans votre navigateur (cliquez dessus, Ctrl+C, collez-la dans la barre d'adresse),",
  ["Download (CurseForge)"] = "Télécharger (CurseForge)",
  ["Below max level, and for a new character's starter spec, Blizzard's Assisted Combat leads while you know few of the spells the priority list expects; DMGAssist's list takes over by itself as you learn more. New spells without a key and unspent talent points get one chat line. Combat > Leveling."] = "Sous le niveau maximum, et avec la spécialisation de départ d'un nouveau personnage, le Combat assisté de Blizzard mène tant que vous connaissez peu des sorts attendus par la liste de priorités ; la liste de DMGAssist prend le relais toute seule à mesure que vous en apprenez. Les nouveaux sorts sans touche et les points de talent restants donnent une ligne dans le chat. Combat > Montée de niveau.",
  ["Fits your UI"] = "S'intègre à votre interface",
  ["Move the HUD in Blizzard's Edit Mode. Masque skins the icons. With a controller, keybinds show as its buttons (Display > Controller button names). Titan Panel and ElvUI data texts get a DMGAssist launcher. Addon authors: DMGAssistAPI."] = "Déplacez le HUD dans le mode Édition de Blizzard. Masque habille les icônes. Avec une manette, les raccourcis s'affichent comme ses boutons (Affichage > Noms des boutons de manette). Titan Panel et les textes de données d'ElvUI ont un lanceur DMGAssist. Pour les auteurs d'addons : DMGAssistAPI.",
  ["DMGAssist is off for %s. /dmga spec on turns it back on."] = "DMGAssist est désactivé pour %s. /dmga spec on le réactive.",
  ["DMGAssist is on for %s."] = "DMGAssist est activé pour %s.",
  ["DMGAssist on or off for the spec you are in (an alt's healing spec, for example)"] = "DMGAssist activé ou désactivé pour la spécialisation actuelle (par exemple la spécialisation de soin d'un reroll)",
  ["Like your action bars: an icon turns red when your target is out of that spell's range, and slot 1 turns blue when you are short of resource for it."] = "Comme sur vos barres d'action : une icône devient rouge quand votre cible est hors de portée de ce sort, et la case 1 devient bleue quand il vous manque la ressource.",
  ["On for this spec"] = "Activé pour cette spécialisation",
  ["Out of range and resource colors"] = "Couleurs de portée et de ressource",
  ["list recommended spells that have no keybind"] = "lister les sorts qui peuvent être recommandés et n'ont pas de raccourci",
  ["test the defensive alert (8 seconds)"] = "simuler une alerte défensive de votre addon de boss (8 s), pour vérifier qu'elle s'affiche",
  ["refresh keybinds"] = "relire les raccourcis",
  ["report an issue or give feedback: describe it, copy the report, open the issue page"] = "signaler un problème ou donner un avis : décrivez-le, copiez le rapport, ouvrez la page des tickets",
  ["save a full decision trace for troubleshooting"] = "enregistrer une trace complète des décisions pour le dépannage",
  ["test the interrupt alert, Assisted Combat, or boss mod detection"] = "tester l'interruption, l'assistant de Blizzard et la détection des addons de boss",
  ["the three setup questions again (where, how big, when to show)"] = "les trois questions de configuration à nouveau (où, quelle taille, quand afficher)",
}
